import * as THREE from 'three';import {createToyKit} from '../world/toy-kit.js';
// Compact geometry for stones/poles; rounded seat tops keep the game's clay language.
export function createCampKit(root){const kit=createToyKit(root),add=(geometry,color,x,y,z,parent=root)=>{const mesh=new THREE.Mesh(geometry,kit.mat(color));mesh.position.set(x,y,z);mesh.castShadow=mesh.receiveShadow=true;parent.add(mesh);return mesh;};const plank=(w,h,d,color,x=0,y=0,z=0,round=.05,parent=root)=>{const b=Math.min(round,h/3,w/3,d/3),s=new THREE.Shape();s.moveTo(-w/2+b,-d/2+b);s.lineTo(w/2-b,-d/2+b);s.lineTo(w/2-b,d/2-b);s.lineTo(-w/2+b,d/2-b);s.closePath();const g=new THREE.ExtrudeGeometry(s,{depth:h-2*b,bevelEnabled:true,bevelThickness:b,bevelSize:b,bevelSegments:1,steps:1,curveSegments:1});g.rotateX(-Math.PI/2);g.translate(0,-(h-2*b)/2,0);return add(g,color,x,y,z,parent);};return {...kit,plank,cylinder:(a,b,h,color,x,y,z,parent=root)=>add(new THREE.CylinderGeometry(a,b,h,8),color,x,y,z,parent),sphere:(r,color,x,y,z,sx=1,sy=1,sz=1,parent=root)=>{const m=add(new THREE.SphereGeometry(r,6,4),color,x,y,z,parent);m.scale.set(sx,sy,sz);return m;},flatBox:(w,h,d,color,x=0,y=0,z=0,round=0,parent=root)=>add(new THREE.BoxGeometry(w,h,d),color,x,y,z,parent)};}
